WITH sales(city,amount) AS (VALUES ('A',100),('A',200),('B',50))
SELECT city, SUM(amount) AS revenue, COUNT(*) AS orders_count
FROM sales GROUP BY city HAVING SUM(amount) >= 100 ORDER BY city;

WITH sales(id,city,amount) AS (VALUES (2,'A',200),(1,'A',200),(3,'B',50))
SELECT id, ROW_NUMBER() OVER (PARTITION BY city ORDER BY amount DESC,id) AS rank
FROM sales ORDER BY city,rank;

WITH sales(city,status,amount) AS (VALUES ('A','paid',100),('A','cancelled',200)),
paid AS (SELECT * FROM sales WHERE status='paid')
SELECT city,SUM(amount) AS revenue FROM paid GROUP BY city;

WITH sales(id,client_id) AS (VALUES (1,'A'),(2,'B')),
clients(id,level) AS (VALUES ('A','gold'))
SELECT s.id,c.level FROM sales s LEFT JOIN clients c ON s.client_id=c.id ORDER BY s.id;
